    p = D / fname
    t = p.read_text()

    # 1. replace the hand-written Deserialize impl
    pat = re.compile(rf"impl<'de> Deserialize<'de> for {ty} \{{.*?^\}}\n", re.S | re.M)
    assert pat.search(t), ty
    indent = "        " if "\n" in body else ""
    body_txt = body if "\n" in body else body
    impl = (f"impl TryFrom<{src}> for {ty} {{\n    type Error = {err};\n\n"
            f"    fn try_from({param}: {src}) -> Result<Self, Self::Error> {{\n        {body_txt}\n    }}\n}}\n")
    t = pat.sub(impl.replace("\\", "\\\\"), t, count=1)

    # 2. derive Deserialize on the public type and point serde at the conversion source
    head = re.compile(rf"((?:^#\[[^\n]*\]\n)+)(pub (?:struct|enum) {ty}\b)", re.M)
    m = head.search(t)
    assert m, ty
    attrs = m.group(1)
    if re.search(r"#\[derive\([^)]*Serialize", attrs):
        attrs = re.sub(r"(#\[derive\([^)]*Serialize)", r"\1, Deserialize", attrs, count=1)
    else:
        attrs = re.sub(r"(#\[derive\([^)]*\)\]\n)", r"\1#[derive(Deserialize)]\n", attrs, count=1)
    if "#[serde(" in attrs:
        attrs = attrs.replace("#[serde(", f'#[serde(try_from = "{src}", ', 1)
    else:
        attrs += f'#[serde(try_from = "{src}")]\n'
    t = t[: m.start()] + attrs + m.group(2) + t[m.end():]
    p.write_text(t)
    print("ok", ty)

